function f() { return 1 }
namespace f { export const n = 2 }
console.log(f())
console.log(f.n)

class A {
  n = 1
  constructor() { console.log(this.n) }
}
new A()

class A {
  #n = 1
  set n(v: number) { this.#n = v + 1 }
  get n() { return this.#n }
}
const a = new A()
a.n = 4
console.log(a.n)

class A { n = 1 }
namespace A { export const m = 2 }
console.log(A.m)

class A {
  static n = 1
  static { this.n = 4 }
}
console.log(A.n)

function assertNum(x: unknown): asserts x is number {
  if (typeof x !== "number") throw new Error("no")
}
try {
  assertNum("a")
  console.log(0)
} catch {
  console.log(1)
}

class A { n() { return 1 } }
class B extends A { override n() { return 2 } }
console.log(new A().n())
console.log(new B().n())

class A { n = 1 }
class B extends A { n = 2 }
console.log(new B().n)

const s = Symbol("k")
const o = { [s]: 6 }
console.log(o[s])
console.log(Object.keys(o).length)

class A {
  constructor(x: string)
  constructor(x: number)
  constructor(public x: string | number) {}
}
console.log(new A(3).x)

const n = 2
enum E { A = n }
console.log(E[2])

class A {
  #n = 5
  static read(x: A) { return x.#n }
}
console.log(A.read(new A()))

namespace N { export class A { n = 1 } }
import A = N.A
console.log(new A().n)
